<?php
declare(strict_types=1);
require_once __DIR__ . '/includes/common.php';
$errors=[];
if ($_SERVER['REQUEST_METHOD']==='POST') {
 verify_csrf(); $action=(string)($_POST['action']??'create');
 if ($action==='status') { $id=(int)($_POST['id']??0); $status=(string)($_POST['status']??''); if(in_array($status,['Mới','Đang xử lý','Đã giao','Đã hủy'],true)){ $st=$pdo->prepare('UPDATE ps_orders SET status=? WHERE id=?');$st->execute([$status,$id]);$_SESSION['flash']=['message'=>'Đã cập nhật trạng thái đơn hàng.','type'=>'success'];} header('Location: orders.php');exit; }
 $customerId=(int)($_POST['customer_id']??0); $productId=(int)($_POST['product_id']??0); $qty=filter_var($_POST['quantity']??null,FILTER_VALIDATE_INT); $note=trim((string)($_POST['note']??''));
 if($customerId<1)$errors[]='Hãy chọn khách hàng.'; if($productId<1)$errors[]='Hãy chọn sản phẩm.'; if($qty===false||$qty<1||$qty>1000)$errors[]='Số lượng phải từ 1 đến 1000.';
 if(!$errors) try { $pdo->beginTransaction(); $c=$pdo->prepare('SELECT id FROM ps_customers WHERE id=?');$c->execute([$customerId]); if(!$c->fetch()) throw new RuntimeException('Khách hàng không tồn tại.'); $p=$pdo->prepare('SELECT id,price,quantity FROM products WHERE id=? FOR UPDATE');$p->execute([$productId]);$product=$p->fetch();if(!$product)throw new RuntimeException('Sản phẩm không tồn tại.');if((int)$product['quantity']<(int)$qty)throw new RuntimeException('Số lượng tồn kho không đủ.');$total=(float)$product['price']*(int)$qty;$ins=$pdo->prepare('INSERT INTO ps_orders(customer_id,total_amount,note) VALUES(?,?,?)');$ins->execute([$customerId,$total,$note?:null]);$orderId=(int)$pdo->lastInsertId();$item=$pdo->prepare('INSERT INTO ps_order_items(order_id,product_id,quantity,unit_price) VALUES(?,?,?,?)');$item->execute([$orderId,$productId,(int)$qty,$product['price']]);$stock=$pdo->prepare('UPDATE products SET quantity=quantity-? WHERE id=?');$stock->execute([(int)$qty,$productId]);$pdo->commit();$_SESSION['flash']=['message'=>'Đã tạo đơn hàng #'.$orderId.' thành công.','type'=>'success'];header('Location: orders.php');exit; } catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$errors[]=$e instanceof RuntimeException?$e->getMessage():'Không thể tạo đơn hàng. Hãy kiểm tra cấu trúc cơ sở dữ liệu.';}
}
$customers=$pdo->query('SELECT id,full_name,phone FROM ps_customers ORDER BY full_name')->fetchAll();$products=$pdo->query('SELECT id,name,price,quantity FROM products ORDER BY name')->fetchAll();$q=trim((string)($_GET['q']??''));$st=$pdo->prepare('SELECT o.*,c.full_name,c.phone,(SELECT COUNT(*) FROM ps_order_items i WHERE i.order_id=o.id) item_count FROM ps_orders o JOIN ps_customers c ON c.id=o.customer_id WHERE CAST(o.id AS CHAR) LIKE ? OR c.full_name LIKE ? ORDER BY o.id DESC');$like="%$q%";$st->execute([$like,$like]);$orders=$st->fetchAll();$flash=$_SESSION['flash']??null;unset($_SESSION['flash']);
?><!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Quản lý đơn hàng</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><nav class="navbar navbar-dark bg-dark"><div class="container"><a class="navbar-brand" href="index.php">PHONE STORE</a><div class="d-flex gap-2"><a class="btn btn-outline-light btn-sm" href="customers.php">Khách hàng</a><a class="btn btn-outline-light btn-sm" href="index.php">Trang chủ</a></div></div></nav><main class="container py-4"><h1 class="h3 mb-3">Quản lý đơn hàng</h1><?php if($flash):?><div class="alert alert-<?=e($flash['type'])?>"><?=e($flash['message'])?></div><?php endif;?><?php if($errors):?><div class="alert alert-danger"><ul class="mb-0"><?php foreach($errors as $x):?><li><?=e($x)?></li><?php endforeach;?></ul></div><?php endif;?><section class="card shadow-sm mb-4"><div class="card-header fw-semibold">Tạo đơn hàng</div><div class="card-body"><form method="post" class="row g-3"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><div class="col-md-4"><label class="form-label">Khách hàng *</label><select required name="customer_id" class="form-select"><option value="">-- Chọn khách hàng --</option><?php foreach($customers as $c):?><option value="<?=(int)$c['id']?>"><?=e($c['full_name'].' — '.$c['phone'])?></option><?php endforeach;?></select><div class="form-text"><a href="customers.php">Thêm khách hàng mới</a></div></div><div class="col-md-4"><label class="form-label">Sản phẩm *</label><select required name="product_id" class="form-select"><?php foreach($products as $p):?><option value="<?=(int)$p['id']?>" <?=((int)$p['quantity']<1?'disabled':'')?>><?=e($p['name'])?> — <?=number_format((float)$p['price'],0,',','.')?> đ (tồn: <?=(int)$p['quantity']?>)</option><?php endforeach;?></select></div><div class="col-md-2"><label class="form-label">Số lượng *</label><input required type="number" min="1" max="1000" name="quantity" value="1" class="form-control"></div><div class="col-md-2"><label class="form-label">Ghi chú</label><input maxlength="500" name="note" class="form-control"></div><div class="col-12"><button class="btn btn-primary" <?=(!$customers||!$products?'disabled':'')?>>Tạo đơn hàng</button></div></form><?php if(!$customers):?><div class="small text-danger mt-2">Cần tạo khách hàng trước khi đặt đơn.</div><?php endif;?></div></section><form class="input-group mb-3"><input name="q" value="<?=e($q)?>" class="form-control" placeholder="Tìm theo mã đơn hoặc tên khách"><button class="btn btn-dark">Tìm</button></form><section class="card shadow-sm"><div class="table-responsive"><table class="table table-striped align-middle mb-0"><thead class="table-dark"><tr><th>Mã đơn</th><th>Khách hàng</th><th>Ngày tạo</th><th>Tổng tiền</th><th>Sản phẩm</th><th>Trạng thái</th></tr></thead><tbody><?php foreach($orders as $o):?><tr><td>#<?=(int)$o['id']?></td><td><?=e($o['full_name'])?><div class="small text-muted"><?=e($o['phone'])?></div></td><td><?=e($o['order_date'])?></td><td><?=number_format((float)$o['total_amount'],0,',','.')?> đ</td><td><?=(int)$o['item_count']?></td><td><form method="post" class="d-flex gap-1"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="status"><input type="hidden" name="id" value="<?=(int)$o['id']?>"><select name="status" class="form-select form-select-sm"><?php foreach(['Mới','Đang xử lý','Đã giao','Đã hủy'] as $s):?><option <?=$s===$o['status']?'selected':''?>><?=e($s)?></option><?php endforeach;?></select><button class="btn btn-sm btn-outline-primary">Lưu</button></form></td></tr><?php endforeach;?><?php if(!$orders):?><tr><td colspan="6" class="text-center text-muted p-4">Chưa có đơn hàng.</td></tr><?php endif;?></tbody></table></div></section><p class="small text-muted mt-3">Tạo đơn sẽ trừ tồn kho; trạng thái có thể cập nhật sau khi tạo.</p></main></body></html>
